    23→@Service
    24→@ConditionalOnProperty(name = ["legacy-sync.enabled"], havingValue = "true", matchIfMissing = false)
    25→class LegacySyncApplicationService(
    26→    private val legacySyncRepository: LegacySyncRepository,
    27→    private val categoryApplicationService: CategoryApplicationService,
    28→    private val mallApplicationService: MallApplicationService,
    29→) {
    30→    private val logger by logger()
    31→
    32→    fun syncToLegacy(changedData: List<ChangedData<LegacyProductData>>) {
    33→        if (changedData.isEmpty()) return
    34→
    35→        val categoryIds =
    36→            changedData
    37→                .flatMap { listOfNotNull(it.afterData?.categoryId, it.beforeData?.categoryId) }
    38→                .distinct()
    39→        val mallIds =
    40→            changedData
    41→                .flatMap { listOfNotNull(it.afterData?.shopId, it.beforeData?.shopId) }
    42→                .distinct()
    43→
    44→        // Category + Mall 조회 병렬화
    45→        val (categories, malls) =
    46→            runBlocking(Dispatchers.IO) {
    47→                val categoriesDeferred =
    48→                    async {
    49→                        if (categoryIds.isEmpty()) {
    50→                            emptyMap()
    51→                        } else {
    52→                            categoryApplicationService.getCachedAllByIds(categoryIds)
    53→                        }
    54→                    }
    55→                val mallsDeferred =
    56→                    async {
    57→                        if (mallIds.isEmpty()) {
    58→                            emptyMap()
    59→                        } else {
    60→                            mallApplicationService.getCachedAllByIds(mallIds)
    61→                        }
    62→                    }
    63→                categoriesDeferred.await() to mallsDeferred.await()
    64→            }
    65→
    66→        // operation별 분류 → push 태스크 수집 → 병렬 실행
    67→        val pushTasks = buildPushTasks(changedData, categories, malls)
    68→
    69→        if (pushTasks.isNotEmpty()) {
    70→            runBlocking(Dispatchers.IO) {
    71→                pushTasks.map { task -> async { task() } }.awaitAll()
    72→            }
    73→        }
    74→    }
    75→
    76→    private fun buildPushTasks(
    77→        changedData: List<ChangedData<LegacyProductData>>,
    78→        categories: Map<Int, CategoryProjection>,
    79→        malls: Map<Int, MallProjection>,
    80→    ): List<() -> Unit> {
    81→        val pushTasks = mutableListOf<() -> Unit>()
    82→        val grouped = changedData.groupBy { it.op }
    83→
    84→        grouped.forEach { (op, items) ->
    85→            val linked = mutableListOf<LinkedProductRequest>()
    86→            val unlinked = mutableListOf<UnlinkedProductRequest>()
    87→            val unlinkedDeletes = mutableListOf<UnlinkedProductDeleteRequest>()
    88→
    89→            items.forEach items@{ item ->
    90→                val data = if (op == Operation.DELETE) item.beforeData else item.afterData
    91→                if (data == null) {
    92→                    logger.warn { "Legacy sync skipped: no data for product id=${item.id}, op=$op" }
    93→                    return@items
    94→                }
    95→
    96→                val mall = malls[data.shopId]
    97→
    98→                when {
    99→                    data.isCatalogMatch -> {
   100→                        linked.add(LegacySyncMapper.toLinkedRequest(data, mall))
   101→                    }
   102→                    op == Operation.DELETE -> {
   103→                        unlinkedDeletes.add(LegacySyncMapper.toUnlinkedDeleteRequest(data, mall))
   104→                    }
   105→                    else -> {
   106→                        val category = categories[data.categoryId]
   107→                        unlinked.add(LegacySyncMapper.toUnlinkedRequest(data, category, mall))
   108→                    }
   109→                }
   110→            }
   111→
   112→            if (linked.isNotEmpty()) pushTasks.add { legacySyncRepository.pushLinkedProducts(linked, op) }
   113→            if (unlinked.isNotEmpty()) pushTasks.add { legacySyncRepository.pushUnlinkedProducts(unlinked, op) }
   114→            if (unlinkedDeletes.isNotEmpty()) pushTasks.add { legacySyncRepository.pushUnlinkedProductDeletes(unlinkedDeletes) }
   115→        }
   116→
   117→        return pushTasks
   118→    }
   119→}
